import heapq
n = 5
g = {0:[(4,1),(1,2)], 1:[(1,3)], 2:[(2,1),(5,3)], 3:[(3,4)], 4:[]}
dist = [float('inf')] * n
dist[0] = 0
pq = [(0, 0)]
while pq:
    d, u = heapq.heappop(pq)
    if d > dist[u]:
        continue
    for w, v in g[u]:
        if d + w < dist[v]:
            dist[v] = d + w
            heapq.heappush(pq, (dist[v], v))
print('dist:', ' '.join(str(x) for x in dist))

