from collections import deque
adj = {0:[1], 1:[2], 2:[0], 3:[4], 4:[]}
deg = {i:0 for i in range(5)}
for u in adj:
    for v in adj[u]:
        deg[v] += 1
q = deque([i for i in range(5) if deg[i]==0])
order = []
while q:
    u = q.popleft(); order.append(u)
    for v in adj[u]:
        deg[v] -= 1
        if deg[v] == 0:
            q.append(v)
print('topo:', order)
```

